function ypReadMarket(){try{const o=JSON.parse(localStorage.getItem(YP_MARKET_KEY)||'null');if(o&&o.version===1)return o;}catch(e){}return ypFreshMarket();}
function ypFreshMarket(){return {version:1,players:[],sales:{},rents:{},board:{},seq:1};}
function ypWriteMarket(s){try{localStorage.setItem(YP_MARKET_KEY,JSON.stringify(s));}catch(e){}}
function ypMarketNext(s){s.seq=(s.seq||1)+1;return 'm'+(s.seq);}
function ypEnsureMarket(){const s=ypReadMarket();if(!s.players||s.players.length<YP_PRETEND_NAMES.length){s.players=YP_PRETEND_NAMES.map((name,i)=>({id:'act'+(i+1),name}));ypWriteMarket(s);}return s;}
function ypActor(id){const s=ypEnsureMarket();return (s.players||[]).find(p=>p.id===id)||null;}
function ypActorName(id){const a=ypActor(id);return a&&a.name||'A player';}
function ypTakeHomeWk(){try{if(typeof salaryNetWk==='function')return Math.max(0,+salaryNetWk()||0);}catch(e){}return 1485;}
function ypMoneySafe(n){n=Math.max(0,Math.round(+n||0));return typeof ypMoneyText==='function'?ypMoneyText(n):('$'+(n.toLocaleString('en-AU')));}
function ypWeekNow(){try{return (typeof G!=='undefined'&&G)?(G.week|0):0;}catch(e){return 0;}}
function ypCodeOf(id){return typeof ypPropertyIdCode==='function'?ypPropertyIdCode(id):'';}
function ypCodeLabel(id){const c=ypCodeOf(id);return /^[A-Z]{3}-\d{4}$/.test(c)?('Property ID: '+c):'this home';}
function ypMarketNotify(msg,propId,kind,offerId){if(typeof notify!=='function')return;notify('info',msg,null,true);try{const n=G&&G.notifs&&G.notifs[0];if(n){n.ypMarket=propId||true;if(kind)n.ypMarketKind=kind;if(offerId)n.ypMarketOffer=offerId;}}catch(e){}if(typeof save==='function')save();}
function ypMarketFeature(id,rec){if(typeof ypBuyFeature==='function'&&rec)return ypBuyFeature(rec);return {type:'Feature',properties:{gameId:id,tone:'home',adopted:true,eligible:true},geometry:(rec&&rec.geometry)||null};}
function ypOwnedRec(id){return typeof ypBuyFor==='function'?ypBuyFor(id):null;}
function ypIsOwnedByPlayer(id){const r=ypOwnedRec(id);return !!(r&&(r.status==='owned'||r.status==='contract'));}
function ypLiveHomeId(){return typeof ypLiveOwnedId==='function'?ypLiveOwnedId():null;}
function ypBedsOf(id,rec){try{return typeof ypHomeBeds==='function'?ypHomeBeds(id,rec||ypMarketFeature(id,rec)):0;}catch(e){return 0;}}
function ypSpareRooms(id,rec){const beds=ypBedsOf(id,rec);return Math.min(2,Math.max(0,(beds|0)-1));}
function ypGuideRent(id,rec){try{const n=typeof ypHomeWeeklyRent==='function'?ypHomeWeeklyRent(id,rec||ypMarketFeature(id,rec)):0;if(n>0)return Math.round(+n);}catch(e){}return 0;}
function ypGuideSale(id,rec){try{const n=typeof ypHomeSalePrice==='function'?ypHomeSalePrice(id,rec||ypMarketFeature(id,rec)):0;if(n>0)return Math.round(+n);}catch(e){}if(rec&&+rec.estimate>0)return Math.round(+rec.estimate);if(rec&&+rec.agreed>0)return Math.round(+rec.agreed);return 0;}

function ypSaleListing(id){const s=ypEnsureMarket();return ypMarketRecordLookup(s.sales,id);}
function ypRentListing(id){const s=ypEnsureMarket();return ypMarketRecordLookup(s.rents,id);}
function ypBoardListing(id){const s=ypEnsureMarket();return ypMarketRecordLookup(s.board,id);}
function ypPropertyIds(id, rec){
  const out=[];
  const add=v=>{
    v=v==null?'':String(v).trim();
    if(!v||out.includes(v))return;
    out.push(v);
  };
  add(id);
  if(rec&&typeof rec==='object'){
    add(rec.id);
    add(rec.gameId);
    add(rec.footprintId);
    add(rec.pid);
    add(rec.propertyId);
    add(rec.lotId);
    add(rec.code);
  }
  if(typeof ypPropertyIdCode==='function'){
    out.slice().forEach(v=>{
      try{const c=ypPropertyIdCode(v);if(c)add(c);}catch(e){}
    });
  }
  return out;
}
function ypMarketRecordLookup(map, id, rec){
  if(!map)return null;
  if(id!=null&&map[id])return map[id];
  rec=rec||(typeof ypBuyFor==='function'?ypBuyFor(id):null)||(typeof ypOwnedRec==='function'?ypOwnedRec(id):null);
  const ids=typeof ypPropertyIds==='function'?ypPropertyIds(id, rec):[id];
  for(let i=0;i<ids.length;i++){
    const k=ids[i];
    if(k!=null&&map[k])return map[k];
  }
  const idset={};
  ids.forEach(k=>{if(k!=null)idset[String(k)]=1;});
  const vals=Object.values(map);
  for(let i=0;i<vals.length;i++){
    const L=vals[i];
    if(L&&L.id&&idset[String(L.id)])return L;
  }
  return null;
}
function ypCanonicalPropertyId(id, rec){
  rec=rec||(typeof ypBuyFor==='function'?ypBuyFor(id):null);
  try{
    const buys=(typeof ypReadBuys==='function'?ypReadBuys().buys:null)||{};
    if(id!=null&&buys[id])return String(id);
    const ids=typeof ypPropertyIds==='function'?ypPropertyIds(id, rec):[id];
    const idset={};
    ids.forEach(k=>{if(k!=null)idset[String(k)]=1;});
    for(const k of Object.keys(buys)){
      if(idset[String(k)])return k;
      const b=buys[k];
      if(!b)continue;
      if((b.id&&idset[String(b.id)])||(b.gameId&&idset[String(b.gameId)])||(b.footprintId&&idset[String(b.footprintId)]))return k;
    }
  }catch(e){}
  if(rec&&rec.id)return String(rec.id);
  return id;
}
function ypRekeyMarketMaps(){
  try{
    const s=typeof ypEnsureMarket==='function'?ypEnsureMarket():null;
    if(!s)return false;
    let changed=false;
    ['sales','rents','board'].forEach(kind=>{
      const map=s[kind];
      if(!map)return;
      Object.keys(map).forEach(key=>{
        const L=map[key];
        if(!L)return;
        const rec=typeof ypBuyFor==='function'?ypBuyFor(L.id||key):null;
        const canon=ypCanonicalPropertyId(L.id||key, rec);
        if(!canon||String(canon)===String(key)){
          if(canon&&L.id&&String(L.id)!==String(canon)){L.id=canon;changed=true;}
          return;
        }
        if(!map[canon]){
          L.id=canon;
          map[canon]=L;
          delete map[key];
          changed=true;
        }else if(map[canon]!==L){
          if(!map[canon].id)map[canon].id=canon;
          delete map[key];
          changed=true;
        }
      });
    });
    if(changed&&typeof ypWriteMarket==='function')ypWriteMarket(s);
    return changed;
  }catch(e){return false;}
}
function ypMarketAsking(id){const L=ypSaleListing(id);if(L&&L.status==='listed'&&+L.asking>0)return Math.round(+L.asking);return 0;}
function ypIsOwnSaleListing(id){const L=ypSaleListing(id);return !!(L&&(L.status==='listed'||L.status==='accepted'||L.status==='agreed'));}

function ypIsInvestment(id){const L=ypRentListing(id);return !!(L&&L.status==='leased'&&L.tenant);}
function ypIsBoardHost(id){const L=ypBoardListing(id);return !!(L&&(L.boarders||[]).some(b=>b&&!b.endedWeek));}
function ypHasOpenBoard(id){const L=ypBoardListing(id);if(!L)return false;if(typeof ypMigrateBoardListing==='function')ypMigrateBoardListing(L);if(typeof ypBoardPending==='function'&&ypBoardPending(L))return true;if(typeof ypBoardUnseenMove==='function'&&ypBoardUnseenMove(L))return true;if(typeof ypBoardIsAdvertising==='function')return ypBoardIsAdvertising(L);return !!(L&&L.status==='advertised'&&+L.boardWk>0);}

function ypPretendSellerId(id){const s=ypEnsureMarket();const list=s.players||[];if(!list.length)return '';let h=0;const t=String(id||'');for(let i=0;i<t.length;i++)h=((h<<5)-h)+t.charCodeAt(i)|0;const n=Math.abs(h)%list.length;return list[n].id;}
function ypIsPretendSale(id){if(ypIsOwnedByPlayer(id)||ypIsOwnSaleListing(id))return false;try{const week=ypWeekNow();const tick=(typeof ypFeedHouseHash==='function'?ypFeedHouseHash('psale|'+week+'|'+id):0)||0;const unit=(tick>>>0)%10;return unit<3;}catch(e){return false;}}
function ypPlayerSaleMark(id){if(ypIsOwnSaleListing(id))return 'Your Listing';return '';}

function ypPlayerSaleListings(place){const out=[];const seen=new Set();const s=ypEnsureMarket();Object.values(s.sales||{}).forEach(L=>{if(!L||(L.status!=='listed'&&L.status!=='agreed'))return;const id=String(L.id||'');if(!id||seen.has(id))return;const rec=ypOwnedRec(id);if(!rec||rec.status!=='owned')return;let lon=+rec.lon,lat=+rec.lat;if((!Number.isFinite(lon)||!Number.isFinite(lat))&&rec.geometry&&typeof ypOuterRings==='function'&&typeof ypFootprintPoint==='function'){try{const ring=ypOuterRings(rec.geometry)[0];const point=ring&&ypFootprintPoint(ring);if(point){lon=point.lon;lat=point.lat;}}catch(e){}}if(place&&Number.isFinite(+place.lon)&&Number.isFinite(+place.lat)&&Number.isFinite(lon)&&Number.isFinite(lat)&&typeof ypDistanceM==='function'&&ypDistanceM(+place.lon,+place.lat,lon,lat)>2000)return;seen.add(id);out.push({id,feature:ypMarketFeature(id,rec),geometry:rec.geometry,official:(typeof ypOfficialSuburb==='function'&&ypOfficialSuburb(id))||(typeof ypSearchedSuburb==='function'?ypSearchedSuburb(place):'')||'',lon,lat,playerListed:true,asking:L.asking,mark:L.status==='listed'?'Your Listing':'Your Listing'});});return out;}

function ypCanListSale(id){const rec=ypOwnedRec(id);if(!rec||rec.status!=='owned')return false;if(ypIsInvestment(id))return false;const L=ypSaleListing(id);if(L&&(L.status==='listed'||L.status==='accepted'||L.status==='agreed'))return false;return true;}

function ypCanListRent(id){const rec=ypOwnedRec(id);if(!rec||rec.status!=='owned')return false;if(ypLiveHomeId()===id)return false;if(ypIsOwnSaleListing(id))return false;const R=ypRentListing(id);if(R&&(R.status==='listed'||R.status==='leased'))return false;return true;}
function ypCanOfferBoard(id){if(ypLiveHomeId()!==id)return false;const rec=ypOwnedRec(id);if(!rec||rec.status!=='owned')return false;if(ypIsOwnSaleListing(id)||ypIsInvestment(id))return false;return ypSpareRooms(id,rec)>0;}

function ypMarketRentWk(){const s=ypEnsureMarket();let n=0;Object.values(s.rents||{}).forEach(L=>{if(L&&L.status==='leased'&&L.tenant)n+=Math.max(0,Math.round(+L.rent||0));});return n;}
function ypMarketBoardWk(){const s=ypEnsureMarket();let n=0;Object.values(s.board||{}).forEach(L=>{(L&&L.boarders||[]).forEach(b=>{if(b&&!b.endedWeek)n+=Math.max(0,Math.round(+b.boardWk||+L.boardWk||0));});});return n;}
function ypMarketShareWk(){let n=0;try{const rooms=(typeof G!=='undefined'&&G&&G.rooms)||{};if(typeof ypOwnRoomSharePeople==='function'){Object.keys(rooms).forEach(id=>{(ypOwnRoomSharePeople(id)||[]).forEach(p=>{n+=Math.max(0,Math.round(+p.price||0));});});if(n>0)return n;}}catch(e){}try{if(typeof roomIncome==='function')n+=Math.max(0,Math.round(+roomIncome()||0));}catch(e){}return n;}
function ypMarketIncomeWk(){return ypMarketRentWk()+ypMarketBoardWk();}

function ypPayOwner(amount,label,id){amount=Math.max(0,Math.round(+amount||0));if(!(amount>0)||typeof G==='undefined'||!G)return;if(!(typeof window!=='undefined'&&window.__ypWeekBudgetCash)){G.cash=(+G.cash||0)+amount;if(typeof ypNoteCatch==='function')ypNoteCatch('income',amount);}if(label)ypMarketNotify(label,id);}

function ypMarketUnit(key){let h=2166136261;const s=String(key||'');for(let i=0;i<s.length;i++)h=Math.imul(h^s.charCodeAt(i),16777619);return((h>>>0)%1000000)/1000000;}
function ypBuyerOfferFullRatio(){return 1.08;}
function ypMarketWaitMs(clock){return typeof ypProcessWaitMs==='function'?ypProcessWaitMs(clock):Math.round(60*60*1000*((typeof ypWeekMs==='function'?ypWeekMs(clock):(typeof CFG!=='undefined'&&CFG&&CFG.weekMs)||0)/((typeof YP_WEEK_MS==='number'&&YP_WEEK_MS>0)?YP_WEEK_MS:((typeof CFG!=='undefined'&&CFG&&CFG.weekMs)||60*60*1000))));}
function ypMarketNowMs(clock){clock=clock||(typeof ypReadClock==='function'?ypReadClock():null);if(typeof ypGameMs==='function'&&clock)return ypGameMs(clock);const week=typeof ypWeekNow==='function'?ypWeekNow():0;const weekMs=typeof ypWeekMs==='function'?ypWeekMs(clock):(typeof CFG!=='undefined'&&CFG&&CFG.weekMs)||0;return week*weekMs;}
function ypMarketStampMs(rec,weekKey,msKey){if(rec&&Number.isFinite(+rec[msKey]))return +rec[msKey];const week=rec&&Number.isFinite(+rec[weekKey])?+rec[weekKey]:0;const weekMs=typeof ypWeekMs==='function'?ypWeekMs():(typeof CFG!=='undefined'&&CFG&&CFG.weekMs)||0;return week*weekMs;}
function ypBuyerOfferChance(ask,est,intervalMs){ask=Math.round(+ask||0);est=Math.round(+est||0);if(!(ask>0)||!(est>0))return 0;const r=ask/est;let weekly=0;if(r<=1)weekly=1;else{const fullTo=ypBuyerOfferFullRatio();if(r<=fullTo)weekly=1;else{const floor=0.07,span=1.5-fullTo,t=(r-fullTo)/span;weekly=floor+(1-floor)*Math.exp(-3*Math.max(0,t));}}const weekMs=typeof ypWeekMs==='function'?ypWeekMs():(typeof CFG!=='undefined'&&CFG&&CFG.weekMs)||0;const interval=(+intervalMs>0)?+intervalMs:weekMs;if(!(weekMs>0)||!(interval>0)||interval>=weekMs||weekly>=1)return weekly>=1?1:weekly;return 1-Math.pow(1-weekly,interval/weekMs);}
function ypBuyerOfferAmount(ask,est,unit){ask=Math.round(+ask||0);est=Math.round(+est||0);if(!(ask>0))return 0;if(!(est>0))return ask;if(ask<=est){const floor=Math.round(est*0.92);return Math.min(ask,Math.max(floor,Math.ceil((ask*0.97)/1000)*1000));}unit=Number(unit);if(!Number.isFinite(unit))unit=0.5;unit=Math.min(1,Math.max(0,unit));const low=Math.round(est*0.90),high=Math.round(est*1.02);let amount=Math.round((low+(high-low)*unit)/1000)*1000;amount=Math.min(high,Math.max(low,amount));return Math.min(ask,amount);}
function ypBuyerOfferThins(ask,est){ask=Math.round(+ask||0);est=Math.round(+est||0);if(!(ask>0)||!(est>0))return false;return ask>Math.round(est*ypBuyerOfferFullRatio());}
function ypTickMarket(){if(typeof G==='undefined'||!G)return;const week=ypWeekNow();const nowMs=ypMarketNowMs();const wait=ypMarketWaitMs();const weekMs=typeof ypWeekMs==='function'?ypWeekMs():(typeof CFG!=='undefined'&&CFG&&CFG.weekMs)||0;const s=ypEnsureMarket();let changed=false;const take=ypTakeHomeWk();
  Object.values(s.sales||{}).forEach(L=>{if(!L)return;if(L.status==='listed'){(L.offers||[]).forEach(o=>{if(o.status==='open'&&week>=(+o.expires||0)){o.status='expired';changed=true;ypMarketNotify('An offer on '+ypCodeLabel(L.id)+' has ended.',L.id,'offer');}});const open=(L.offers||[]).some(o=>o.status==='open'||o.status==='countered');if(!open){const rec=ypOwnedRec(L.id);const est=ypGuideSale(L.id,rec)||Math.round(+L.asking||0);const ask=Math.round(+L.asking||est);const start=ypMarketStampMs(L,'listedWeek','listedGameMs');const due=Number.isFinite(+L.nextOfferGameMs)?+L.nextOfferGameMs:start+wait;if(ask>0&&nowMs>=due){let checkAt=due,got=false,steps=0;changed=true;while(checkAt<=nowMs&&!got&&steps<200){const chance=typeof ypBuyerOfferChance==='function'?ypBuyerOfferChance(ask,est,wait):1;const roll=typeof ypMarketUnit==='function'?ypMarketUnit(['offer',L.id,week,ask,est,checkAt].join(':')):0;L.nextOfferGameMs=checkAt+wait;if(roll<chance){const buyer=ypPickFreeActor(s,[]);if(buyer){const unit=typeof ypMarketUnit==='function'?ypMarketUnit(['amount',L.id,week,ask,est,buyer.id].join(':')):0.5;const amount=typeof ypBuyerOfferAmount==='function'?ypBuyerOfferAmount(ask,est,unit):Math.min(ask,Math.max(Math.round(est*0.92),Math.ceil(((ask>est?est:ask)*0.97)/1000)*1000));if(amount>0){const off={id:ypMarketNext(s),from:buyer.id,amount,week,expires:week+YP_MARKET_OFFER_WEEKS,status:'open',round:0,ask};L.offers=L.offers||[];L.offers.push(off);L.seededOffer=1;got=true;ypMarketNotify(ypActorName(buyer.id)+' has offered '+ypMoneySafe(amount)+' on '+ypCodeLabel(L.id)+'.',L.id,'offer',off.id);if(typeof ypSellEvent==='function')ypSellEvent(L.id,'saleOffer',ypActorName(buyer.id)+' offered '+ypMoneySafe(amount)+'.');ypFlushOfferPopup();}}}checkAt+=wait;steps++;}if(!got)L.nextOfferGameMs=nowMs+wait;}}}
    if(L.status==='agreed'&&Number.isFinite(+L.keysWeek)&&week>=(+L.keysWeek|0)){ypSettlePlayerSale(s,L,week);changed=true;}
    (L.offers||[]).forEach(o=>{if(L.status!=='listed'||o.status!=='countered')return;const due=Number.isFinite(+o.replyGameMs)?+o.replyGameMs:(Number.isFinite(+o.replyWeek)?(+o.replyWeek)*weekMs:Infinity);if(due<=nowMs&&!o.replied){o.replied=1;changed=true;ypBuyerReply(s,L,o,week);}});
  });
  Object.values(s.rents||{}).forEach(L=>{if(!L)return;const start=ypMarketStampMs(L,'listedWeek','listedGameMs');if(L.status==='listed'&&nowMs>=start+wait&&!L.seededApp){const cap=Math.floor(take*0.30);if(+L.rent>0&&+L.rent<=cap){const who=ypPickFreeActor(s,[]);if(who){const months=(L.terms&&L.terms[0])||12;const app={id:ypMarketNext(s),from:who.id,week,months,status:'pending'};L.apps=L.apps||[];L.apps.push(app);L.seededApp=1;changed=true;ypMarketNotify(ypActorName(who.id)+' has applied to rent '+ypCodeLabel(L.id)+'.',L.id,'rent');}}}
    if(L.status==='leased'&&L.tenant){const start=Number.isFinite(+L.startWeek)?(+L.startWeek|0):week;if(week>start){const last=L.lastChargedWeek==null?start:(+L.lastChargedWeek|0);if(week>last){const due=(week-last)*Math.round(+L.rent||0);L.lastChargedWeek=week;changed=true;if(due>0)ypPayOwner(due,'Rent received: '+ypMoneySafe(due)+' for '+ypCodeLabel(L.id)+'.',L.id);}}
      if(Number.isFinite(+L.endWeek)&&week>=(+L.endWeek|0)&&!L.m2m){L.m2m=1;changed=true;ypMarketNotify('The lease at '+ypCodeLabel(L.id)+' continues week by week at the same rent.',L.id,'rent');}}
  });
  if(typeof ypMigrateBoardListings==='function')ypMigrateBoardListings();
  Object.values(s.board||{}).forEach(L=>{if(!L)return;if(typeof ypMigrateBoardListing==='function')ypMigrateBoardListing(L);const rec=typeof ypOwnedRec==='function'?ypOwnedRec(L.id):null;const room=typeof ypBoardFree==='function'?ypBoardFree(L.id,rec):{cap:ypSpareRooms(L.id,rec),free:Math.max(0,ypSpareRooms(L.id,rec)-(L.boarders||[]).filter(b=>b&&!b.endedWeek).length)};
    if(L.status==='advertised'&&!(room.free>0)&&!((L.requests||[]).some(r=>r&&r.status==='pending'))&&!(L.moveInId&&!L.moveInSeen)){L.status='idle';L.stopped=1;changed=true;}
    const pending=(L.requests||[]).some(r=>r&&r.status==='pending');
    const offered=ypMarketStampMs(L,'offeredWeek','offeredGameMs');
    if(L.status==='advertised'&&!pending&&room.free>0&&nowMs>=offered+wait&&!L.seededReq){const who=ypPickFreeActor(s,(L.boarders||[]).map(b=>b&&b.who).concat((L.requests||[]).map(r=>r&&r.from)));if(who){L.requests=L.requests||[];const req={id:ypMarketNext(s),from:who.id,week,status:'pending',amount:Math.round(+L.boardWk||0)};L.requests.push(req);L.seededReq=1;changed=true;ypMarketNotify(ypActorName(who.id)+' has asked to board at '+ypCodeLabel(L.id)+'. Tap to review.',L.id,'board',req.id);if(typeof ypBoardEvent==='function')ypBoardEvent(L.id,'boardRequest',ypActorName(who.id)+' asked to board at '+(typeof ypMoneySafe==='function'?ypMoneySafe(L.boardWk):L.boardWk)+' a week.');}}
    (L.boarders||[]).forEach(b=>{if(!b||b.endedWeek)return;const start=Number.isFinite(+b.startWeek)?(+b.startWeek|0):week;if(week>start){const last=b.lastChargedWeek==null?start:(+b.lastChargedWeek|0);if(week>last){const due=(week-last)*Math.round(+b.boardWk||+L.boardWk||0);b.lastChargedWeek=week;changed=true;if(due>0)ypPayOwner(due,'Board received: '+ypMoneySafe(due)+' at '+ypCodeLabel(L.id)+'.',L.id);}}});
  });
  const share=typeof ypMarketShareWk==='function'?ypMarketShareWk():0;if(share>0){const last=s.shareLastChargedWeek==null?-1:(+s.shareLastChargedWeek|0);if(week>last){s.shareLastChargedWeek=week;changed=true;ypPayOwner(share,'Room share received: '+ypMoneySafe(share)+'.');}}
  if(changed){ypWriteMarket(s);if(typeof hud==='function')try{hud();}catch(e){}ypFlushOfferPopup();}}

function ypPickFreeActor(s,used){const busy=new Set(used||[]);Object.values(s.rents||{}).forEach(L=>{if(L&&L.tenant)busy.add(L.tenant);(L.apps||[]).forEach(a=>{if(a.status==='pending'||a.status==='approved')busy.add(a.from);});});Object.values(s.sales||{}).forEach(L=>{(L.offers||[]).forEach(o=>{if(o.status==='open'||o.status==='countered'||o.status==='accepted')busy.add(o.from);});if(L.buyer)busy.add(L.buyer);});Object.values(s.board||{}).forEach(L=>{(L.boarders||[]).forEach(b=>{if(b&&!b.endedWeek)busy.add(b.who);});(L.requests||[]).forEach(r=>{if(r.status==='pending'||r.status==='accepted')busy.add(r.from);});(L.invites||[]).forEach(i=>{if(i.status==='sent'||i.status==='accepted')busy.add(i.to);});});const free=(s.players||[]).filter(p=>!busy.has(p.id));if(!free.length)return (s.players||[])[0]||null;return free[Math.floor((ypWeekNow()*17+free.length*3)%free.length)]||free[0];}

function ypSaleOfferStatusText(o){if(!o)return 'No Offers Yet';if(o.status==='countered'){const amt=Math.round(+o.ask||+o.amount||0);return 'Countered '+(amt?ypMoneySafe(amt):'')+', Awaiting Reply';}if(o.status==='open')return 'Offer Received '+ypMoneySafe(o.amount);if(o.status==='accepted')return 'Offer Accepted '+ypMoneySafe(o.amount);return 'No Offers Yet';}
function ypBuyerReplyDecision(counter,last,est,unit,rounds){counter=Math.round(+counter||0);last=Math.round(+last||0);est=Math.round(+est||0);rounds=Math.max(0,+rounds||0);unit=Number(unit);if(!Number.isFinite(unit))unit=0.5;unit=Math.min(1,Math.max(0,unit));if(!(counter>0))return 'walk';if(counter<=last)return 'accept';if(est>0&&counter<=est)return 'accept';if(rounds>=(typeof YP_MARKET_COUNTER_ROUNDS==='number'?YP_MARKET_COUNTER_ROUNDS:4))return (est>0&&counter<=Math.round(est*1.08))?'accept':'walk';let accept=0,walk=0;if(est>0){const r=counter/est;accept=Math.exp(-4*Math.max(0,r-1.05)/0.25);walk=1-Math.exp(-3*Math.max(0,r-1.08)/0.42);}else{const r=last>0?counter/last:2;accept=r<=1.1?0.7:Math.exp(-3*Math.max(0,r-1.1));walk=r<=1.2?0.05:Math.min(0.85,r-1.15);}const sum=accept+walk;if(sum>1){accept/=sum;walk/=sum;}if(unit<accept)return 'accept';if(unit<accept+walk)return 'walk';return 'mid';}
function ypBuyerReply(s,L,o,week){const rec=ypOwnedRec(L.id);const est=ypGuideSale(L.id,rec)||Math.round(+L.asking||0);const counter=Math.round(+o.ask||0);const last=Math.round(+o.amount||0);const unit=typeof ypMarketUnit==='function'?ypMarketUnit(['reply',L.id,o.id,week,counter,last,est].join(':')):0.5;const decision=ypBuyerReplyDecision(counter,last,est,unit,+o.round||0);if(decision==='accept'||(decision==='mid'&&!(counter>last))){o.buyerReply='accepted';o.replyPopupShown=0;o.amount=counter;ypAcceptSaleOffer(s,L,o,week);ypMarketNotify(ypActorName(o.from)+' has agreed to '+ypMoneySafe(counter)+' on '+ypCodeLabel(L.id)+'.',L.id,'offer');return;}if(decision==='walk'){o.status='declined';o.buyerReply='declined';o.replyPopupShown=0;ypMarketNotify(ypActorName(o.from)+' has walked away from '+ypCodeLabel(L.id)+'.',L.id,'offer');return;}const mid=Math.ceil(((counter+last)/2)/1000)*1000;const amount=Math.min(counter,Math.max(last,mid));if(!(amount>last)||amount>=counter){o.buyerReply='accepted';o.replyPopupShown=0;o.amount=counter;ypAcceptSaleOffer(s,L,o,week);ypMarketNotify(ypActorName(o.from)+' has agreed to '+ypMoneySafe(counter)+' on '+ypCodeLabel(L.id)+'.',L.id,'offer');return;}o.prevAmount=last;o.amount=amount;o.status='open';o.expires=week+YP_MARKET_OFFER_WEEKS;o.round=(+o.round||0)+1;delete o.replied;delete o.buyerReply;o.popupShown=0;ypMarketNotify(ypActorName(o.from)+' has offered '+ypMoneySafe(o.amount)+' on '+ypCodeLabel(L.id)+'.',L.id,'offer');}

function ypAcceptSaleOffer(s,L,o,week){week=week||ypWeekNow();(L.offers||[]).forEach(x=>{if(x!==o&&(x.status==='open'||x.status==='countered'))x.status='declined';});o.status='accepted';L.status='accepted';L.agreed=Math.round(+o.amount||0);L.buyer=o.from;delete L.keysWeek;delete L.keysGameMs;delete L.signedWeek;delete L.signedGameMs;ypWriteMarket(s);if(typeof ypStopBoardAdvert==='function')ypStopBoardAdvert(L.id);const name=typeof ypActorName==='function'?ypActorName(o.from):'A player';if(typeof ypSellEvent==='function')ypSellEvent(L.id,'saleAccepted',name+'\'s offer of '+(typeof ypMoneySafe==='function'?ypMoneySafe(L.agreed):L.agreed)+' accepted.');}


function ypSettlePlayerSale(s,L,week){if(!L||L.status==='settled')return;if(L.status!=='agreed')return;week=week||ypWeekNow();s=s||(typeof ypEnsureMarket==='function'?ypEnsureMarket():null);const rec=ypOwnedRec(L.id);const lived=typeof ypLiveHomeId==='function'&&ypLiveHomeId()===L.id;const q=typeof ypSellMoney==='function'?ypSellMoney(L.id):null;const price=q?q.price:Math.round(+L.agreed||0);const loan=q?q.loan:(rec&&typeof ypLoanOwing==='function'?Math.max(0,Math.round(+ypLoanOwing(rec)||0)):Math.max(0,Math.round(+(rec&&rec.loan)||0)));const toBank=q?q.toBank:Math.max(0,price-loan);const shortfall=q?q.shortfall:Math.max(0,loan-price);L.salePrice=price;L.loanPaid=loan;L.toBank=toBank;L.shortfall=shortfall;if(typeof G!=='undefined'&&G){if(toBank>0)G.cash=(+G.cash||0)+toBank;else if(shortfall>0)G.cash=(+G.cash||0)-shortfall;if(typeof ypNoteCatch==='function'){if(toBank>0)ypNoteCatch('income',toBank);else if(shortfall>0)ypNoteCatch('expense',shortfall);}if(lived){G.housing=G.housing==='home'?'':G.housing;if(G.housing==='')G.homeChosen=0;G.ypNeedLiveNext=1;}}if(rec){rec.status='sold';rec.soldWeek=week;rec.soldPrice=price;rec.loan=0;rec.intent=rec.intent||'';try{if(typeof ypSaveBuy==='function')ypSaveBuy(rec);}catch(e){}}if(typeof ypEndSaleOccupants==='function')ypEndSaleOccupants(L.id,week,s);L.status='settled';L.settledWeek=week;if(s&&typeof ypWriteMarket==='function')ypWriteMarket(s);const netTxt=shortfall?(' You paid '+(q?q.shortfallText:(typeof ypMoneySafe==='function'?ypMoneySafe(shortfall):shortfall))+' at settlement.'):(' '+(q?q.toBankText:(typeof ypMoneySafe==='function'?ypMoneySafe(toBank):toBank))+' is in your bank.');if(typeof ypSellEvent==='function')ypSellEvent(L.id,'saleSettled','Sale price '+(q?q.priceText:(typeof ypMoneySafe==='function'?ypMoneySafe(price):price))+'. Loan paid out '+(q?q.loanText:(typeof ypMoneySafe==='function'?ypMoneySafe(loan):loan))+'.'+netTxt);ypMarketNotify('The sale has settled on '+ypCodeLabel(L.id)+'.'+netTxt+' Tap to complete handover.',L.id,'sale');}
function ypSellOrder(){return ['offer','reply','confirm','settle','keys'];}
function ypSellTitles(step,L){const titles={offer:'Offer Received',reply:'Your Reply',confirm:'Sign The Sale Contract',settle:'Under Contract',keys:'Handover'};return titles[step]||'';}
function ypSellMoney(id){const L=typeof ypSaleListing==='function'?ypSaleListing(id):null;const rec=typeof ypOwnedRec==='function'?ypOwnedRec(id):null;const price=Math.max(0,Math.round(+(L&&(L.salePrice!=null?L.salePrice:L.agreed))||0));let loan;if(L&&Number.isFinite(+L.loanPaid))loan=Math.max(0,Math.round(+L.loanPaid));else loan=rec&&typeof ypLoanOwing==='function'?Math.max(0,Math.round(+ypLoanOwing(rec)||0)):Math.max(0,Math.round(+(rec&&rec.loan)||0));const net=price-loan;const money=n=>typeof ypMoneySafe==='function'?ypMoneySafe(n):(typeof ypNetMoney==='function'?ypNetMoney(n):('$'+(Math.max(0,Math.round(+n||0)).toLocaleString('en-AU'))));return {price,loan,net,toBank:net>=0?net:0,shortfall:net<0?-net:0,priceText:money(price),loanText:money(loan),toBankText:money(net>=0?net:0),shortfallText:money(net<0?-net:0)};}
function ypSellEvent(id,kind,reason,clock){clock=clock||(typeof ypReadClock==='function'?ypReadClock():null);const gm=clock&&typeof ypGameMs==='function'?ypGameMs(clock):(Date.now());const at=clock&&clock.wall;const ev=typeof ypHistoryEvent==='function'?ypHistoryEvent(id,kind,gm,reason,at):null;if(ev&&typeof ypRecordHistory==='function')ypRecordHistory([ev]);return ev;}
function ypSellBg(kind){if(typeof ypAgentClipShipped==='function'&&ypAgentClipShipped(kind)&&typeof ypAgentClip==='function'){ypAgentClip(kind);return;}if(typeof ypAgentClip==='function')ypAgentClip('office');}
function ypSellClipOnce(kind,then){then=then||(()=>{});if(typeof ypAgentClipShipped==='function'&&ypAgentClipShipped(kind)&&typeof ypClipOnce==='function'){ypClipOnce(kind,then);return;}then();}
function ypSellAcceptedOffer(L){return (L&&L.offers||[]).find(o=>o&&o.status==='accepted')||null;}
function ypSellOpenOffer(L,offerId){const list=(L&&L.offers)||[];if(offerId)return list.find(o=>o&&String(o.id)===String(offerId))||null;return list.find(o=>o&&(o.status==='open'||o.status==='countered'))||null;}
function ypResumeSell(id,offerId){const L=typeof ypSaleListing==='function'?ypSaleListing(id):null;if(!L){if(typeof ypOpenManageSale==='function')ypOpenManageSale(id);return;}if(L.status==='settled'){ypOpenSellStep(id,'keys');return;}if(L.status==='agreed'){const week=typeof ypWeekNow==='function'?ypWeekNow():0;if(Number.isFinite(+L.keysWeek)&&week>=(+L.keysWeek|0)&&typeof ypSettlePlayerSale==='function'){try{ypSettlePlayerSale(ypEnsureMarket(),L,week);}catch(e){}}ypOpenSellStep(id,(L.status==='settled'||(Number.isFinite(+L.keysWeek)&&week>=(+L.keysWeek|0)))?'keys':'settle');return;}if(L.status==='accepted'){ypOpenSellStep(id,'confirm');return;}const off=ypSellOpenOffer(L,offerId);if(off){ypOpenSellStep(id,'offer',off.id);return;}if(typeof ypOpenManageSale==='function')ypOpenManageSale(id);}
function ypSignSaleContract(id){const s=typeof ypEnsureMarket==='function'?ypEnsureMarket():null;const L=s&&s.sales&&s.sales[id];if(!L||(L.status!=='accepted'&&!(L.status==='agreed'&&!L.keysWeek)))return {ok:false,why:'This sale is not ready to sign.'};const week=typeof ypWeekNow==='function'?ypWeekNow():0;const now=typeof ypMarketNowMs==='function'?ypMarketNowMs():0;const weekMs=(typeof ypWeekMs==='function'?ypWeekMs():0)||0;const hold=typeof YP_MARKET_SETTLE_WEEKS==='number'?YP_MARKET_SETTLE_WEEKS:4;L.status='agreed';L.signedWeek=week;L.signedGameMs=now;L.keysWeek=week+hold;if(weekMs>0)L.keysGameMs=now+hold*weekMs;if(typeof ypWriteMarket==='function')ypWriteMarket(s);if(typeof ypStopBoardAdvert==='function')ypStopBoardAdvert(id);const q=ypSellMoney(id);ypSellEvent(id,'saleContract','Sale price '+q.priceText+'. Loan paid out '+q.loanText+'. '+(q.shortfall?'You pay '+q.shortfallText+' at settlement.':'Money to your bank '+q.toBankText+' at settlement.')+ ' Nothing is paid until settlement.');if(typeof ypMarketNotify==='function')ypMarketNotify('You signed the sale contract on '+(typeof ypCodeLabel==='function'?ypCodeLabel(id):'your home')+'. Settlement is in '+hold+' game weeks. Nothing is paid until then.',id,'sale');return {ok:true,L};}
