function ypMountOwnedMarketActions(card,rec){if(!card||!rec||(rec.status!=='owned'&&rec.status!=='contract'))return;const id=typeof ypCanonicalPropertyId==='function'?ypCanonicalPropertyId(rec.id,rec):rec.id;const going=typeof ypMountGoingOn==='function'?ypMountGoingOn(card,id,rec):{};if(going&&going.sec){const anchor=[...card.querySelectorAll('.yp-facts,.yp-flow,.yp-limit')].find(n=>n&&!going.sec.contains(n));if(anchor)anchor.before(going.sec);}const saleBusy=!!(going&&going.saleBusy);const advertised=!!(going&&going.advertised);if(rec.status==='owned'&&typeof ypCanListSale==='function'&&ypCanListSale(id))ypMarketBtn(card,'hwb yp-btn-primary','List For Sale',()=>ypOpenListForSale(id),'yp-list-sale');if(rec.status==='owned'&&typeof ypCanListRent==='function'&&ypCanListRent(id))ypMarketBtn(card,'hwx','List For Rent',()=>ypOpenListForRent(id),'yp-list-rent');if(rec.status==='owned'&&!saleBusy&&!advertised&&typeof ypCanOfferBoard==='function'&&ypCanOfferBoard(id))ypMarketBtn(card,'hwb yp-btn-primary','Offer A Room',()=>ypOpenOfferRoom(id),'yp-offer-room-btn');if(advertised)ypMarketBtn(card,'hwx','Stop Advertising',()=>{if(typeof ypStopBoardAdvert==='function')ypStopBoardAdvert(id);const panel=document.getElementById('yp-sale-detail');if(panel)panel.remove();if(typeof ypOpenSaleDetail==='function')ypOpenSaleDetail(ypMarketFeature(id,rec));},'yp-board-stop');}

function ypSaleDetailOverrides(id,rec,st,price,facts,flow){const out={price,flow,label:null,residenceTitle:'',statusExtra:''};if(st==='contract'){out.label='Awaiting Settlement';if(rec&&+rec.agreed>0)out.price=Math.round(+rec.agreed);else if(rec&&+rec.price>0)out.price=Math.round(+rec.price);return out;}if(st==='owned'&&ypIsInvestment(id)){out.residenceTitle='';out.label='Your Investment';out.price=price;out.flow=(typeof ypInvestmentRows==='function'?ypInvestmentRows(rec,price):flow);return out;}if(st==='owned'&&ypIsOwnSaleListing(id)){const L=ypSaleListing(id);out.label=L&&L.status==='agreed'?'Awaiting Settlement':(L&&L.status==='accepted'?'Sale Agreed':'Your Listing');if(L&&+L.asking>0&&L.status==='listed')out.price=Math.round(+L.asking);if(L&&(L.status==='accepted'||L.status==='agreed')&&+L.agreed>0)out.price=Math.round(+L.agreed);out.flow=flow||[];return out;}return out;}


function ypOwnSaleRows(L){if(!L)return [];const rows=[];if(L.status==='listed'&&+L.asking>0)rows.push({label:'Asking Price',value:ypMoneySafe(L.asking)});if(L.status==='accepted'||L.status==='agreed'){rows.push({label:'Agreed Price',value:ypMoneySafe(L.agreed)});rows.push({label:'Status',value:L.status==='agreed'?'Awaiting Settlement':'Sale Agreed'});if(L.status==='agreed'&&Number.isFinite(+L.keysWeek))rows.push({label:'Keys',value:typeof ypGameWeekLabel==='function'?ypGameWeekLabel(L.keysWeek):('Week '+L.keysWeek)});}const live=(L.offers||[]).filter(o=>o.status==='open'||o.status==='countered'||o.status==='accepted');live.forEach(o=>{if(o.status==='countered')rows.push({label:'Offer Status',value:typeof ypSaleOfferStatusText==='function'?ypSaleOfferStatusText(o):('Countered '+ypMoneySafe(o.ask)+', Awaiting Reply')});else if(o.status==='open')rows.push({label:'Offer Status',value:'Offer Received '+ypMoneySafe(o.amount)});else if(o.status==='accepted')rows.push({label:'Offer Status',value:ypActorName(o.from)+' accepted '+ypMoneySafe(o.amount)});});return rows;}


function ypInvestmentRows(rec,price){const L=ypRentListing(rec&&rec.id);const rows=[];if(typeof ypResidenceRows==='function'){/* keep cost history off this card? show rental breakdown only, like Your rental */}rows.push({subhead:true,label:'Your Rental Income'});if(L){if(+L.rent>0)rows.push({label:'Weekly Rent',value:ypMoneySafe(L.rent)});if(+L.bond>0)rows.push({label:'Bond',value:ypMoneySafe(L.bond),hint:(+L.bondWeeks===1?'1 week':((L.bondWeeks||0)+' weeks'))+' held'});rows.push({label:'Lease Length',value:(L.months||12)+' months'});if(Number.isFinite(+L.startWeek))rows.push({label:'Lease Start',value:typeof ypGameWeekLabel==='function'?ypGameWeekLabel(L.startWeek):('Week '+L.startWeek)});if(L.m2m)rows.push({label:'Lease Ends',value:'Week to week'});else if(Number.isFinite(+L.endWeek))rows.push({label:'Lease Ends',value:typeof ypGameWeekLabel==='function'?ypGameWeekLabel(L.endWeek):('Week '+L.endWeek)});if(L.tenant)rows.push({label:'Tenant',value:ypActorName(L.tenant)});}const repay=rec&&typeof ypWeeklyRepay==='function'?ypWeeklyRepay(rec):0;if(repay>0)rows.push({label:'Weekly Repayment',value:ypMoneySafe(repay)});return rows;}

function ypOpenListForSale(id){const rec=ypOwnedRec(id);if(!rec||!ypCanListSale(id))return;const est=ypGuideSale(id,rec);const ui=ypMarketPanel('yp-list-sale','List For Sale','Your home');ypMarketText(ui.card,'Set an asking price. The game estimate is a guide.');if(est>0)ypMarketFlow(ui.card,[{label:'Game Estimate',value:ypMoneySafe(est),hint:'A guide only'}]);const input=document.createElement('input');input.type='number';input.id='yp-ask-amount';input.inputMode='numeric';input.min='1';input.step='1000';input.value=String(est||'');input.setAttribute('aria-label','Asking price in dollars');ui.card.appendChild(input);ypMarketBtn(ui.card,'hwb','List this home',()=>{const ask=Math.round(+input.value||0);if(!(ask>0))return;const s=ypEnsureMarket();s.sales[id]={id,asking:ask,listedWeek:ypWeekNow(),listedGameMs:ypMarketNowMs(),status:'listed',offers:[]};ypWriteMarket(s);if(typeof ypStopBoardAdvert==='function')ypStopBoardAdvert(id);ypMarketNotify('Your home is listed for sale at '+ypMoneySafe(ask)+'.',id,'sale');ui.panel.remove();if(typeof ypOpenSaleDetail==='function')ypOpenSaleDetail(ypMarketFeature(id,rec));},'yp-list-sale-go');ypMarketBtn(ui.card,'hwx','Cancel',()=>ui.panel.remove());ypMarketMount(ui.panel,ui.card);}

function ypOpenManageSale(id){const L=ypSaleListing(id);const rec=ypOwnedRec(id);if(!L)return;if((L.status==='accepted'||L.status==='agreed'||L.status==='settled')&&typeof ypResumeSell==='function'){ypResumeSell(id);return;}const title=L.status==='agreed'?'Awaiting Settlement':(L.status==='accepted'?'Sale Agreed':'Your Listing');const ui=ypMarketPanel('yp-manage-sale',title,ypCodeLabel(id));ypMarketFlow(ui.card,ypOwnSaleRows(L));const open=(L.offers||[]).filter(o=>o.status==='open'||o.status==='countered');open.forEach(o=>{if(o.status==='open')ypMarketBtn(ui.card,'hwb',ypActorName(o.from)+' offers '+ypMoneySafe(o.amount),()=>{ui.panel.remove();if(typeof ypOpenSellStep==='function')ypOpenSellStep(id,'offer',o.id);else ypOpenSellerOffer(id,o.id);});});if(L.status==='listed')ypMarketBtn(ui.card,'hwx','Withdraw Listing',()=>{if(L.offers&&L.offers.some(o=>o.status==='accepted'))return;const s=ypEnsureMarket();if(s.sales[id])s.sales[id].status='withdrawn';ypWriteMarket(s);ypMarketNotify('You have withdrawn the listing for '+ypCodeLabel(id)+'.',id,'sale');ui.panel.remove();if(rec&&typeof ypOpenSaleDetail==='function')ypOpenSaleDetail(ypMarketFeature(id,rec));},'yp-withdraw-sale');ypMarketBtn(ui.card,'hwx','Back',()=>{ui.panel.remove();if(rec&&typeof ypOpenSaleDetail==='function')ypOpenSaleDetail(ypMarketFeature(id,rec));});ypMarketMount(ui.panel,ui.card);}


function ypSaleOfferIsOpen(o){return !!(o&&o.status==='open');}
