function ypNextUnshownBoardRequest(){try{const s=ypEnsureMarket();for(const L of Object.values(s.board||{})){if(!L)continue;const r=(L.requests||[]).find(x=>x&&x.status==='pending'&&!x.popupShown);if(r)return {id:L.id,reqId:r.id};}}catch(e){}return null;}function ypFlushOfferPopup(){try{if(ypFlushOfferPopup._t){clearTimeout(ypFlushOfferPopup._t);ypFlushOfferPopup._t=0;}if(document.getElementById('yp-seller-offer')||document.getElementById('yp-board-request')||document.getElementById('yp-buyer-reply')||document.getElementById('yp-seller-counter'))return;const nextReply=typeof ypNextUnshownBuyerReply==='function'?ypNextUnshownBuyerReply():null;const nextSale=ypNextUnshownSaleOffer();const nextBoard=typeof ypNextUnshownBoardRequest==='function'?ypNextUnshownBoardRequest():null;if(!nextReply&&!nextSale&&!nextBoard)return;if(ypOfferPopupBlocked()){ypFlushOfferPopup._t=setTimeout(ypFlushOfferPopup,600);return;}if(nextReply&&typeof ypOpenBuyerReply==='function'){ypOpenBuyerReply(nextReply.id,nextReply.offerId);return;}if(nextSale){if(typeof ypOpenSellerOffer==='function')ypOpenSellerOffer(nextSale.id,nextSale.offerId);return;}if(nextBoard&&typeof ypOpenBoardRequest==='function')ypOpenBoardRequest(nextBoard.id,nextBoard.reqId);}catch(e){}}
