function ypOpenSellerOffer(id,offerId){if(typeof ypOpenSellStep==='function'){ypOpenSellStep(id,'offer',offerId);return;}}


function ypMarketVal(s){s=String(s||'').trim();if(!s)return '';return s.charAt(0).toUpperCase()+s.slice(1);}
function ypParseDollars(s){const digits=String(s==null?'':s).replace(/[^0-9]/g,'');if(!digits)return 0;const n=Math.round(+digits);return Number.isFinite(n)&&n>0?n:0;}
function ypDollarsText(n){n=Math.round(+n||0);if(!(n>0))return '';return typeof ypMoneySafe==='function'?ypMoneySafe(n):(typeof ypMoneyText==='function'?ypMoneyText(n):('$'+n.toLocaleString('en-AU')));}
function ypBindDollarInput(input,onChange){const paint=()=>{const n=ypParseDollars(input.value);input.dataset.amount=n?String(n):'';const shown=n?ypDollarsText(n):'';if(input.value!==shown){input.value=shown;try{const at=shown.length;input.setSelectionRange(at,at);}catch(e){}}if(onChange)onChange(n);};input.addEventListener('input',paint);input.addEventListener('change',paint);paint();return ()=>ypParseDollars(input.dataset.amount||input.value);}
function ypCounterDiffText(counter,offer){const c=Math.round(+counter||0),o=Math.round(+offer||0);if(!(c>0)||!(o>0))return '';if(c===o)return 'Same as their offer';const money=ypDollarsText(Math.abs(c-o));return money+(c>o?' above their offer':' below their offer');}
function ypCounterRoundText(o){const max=typeof YP_MARKET_COUNTER_ROUNDS==='number'?YP_MARKET_COUNTER_ROUNDS:4;const n=Math.max(1,(+((o&&o.round)||0)|0)+1);if(!(max>0)||n>max)return 'Round '+n;return 'Round '+n+' of '+max;}
function ypOwnedWeeksText(weeks){weeks=Math.max(0,Math.round(+weeks||0));const weekWord=n=>n===1?'1 week':(n+' weeks');if(weeks<52)return weekWord(weeks);const years=Math.floor(weeks/52),rem=weeks%52;const yearWord=years===1?'1 year':(years+' years');if(!rem)return yearWord+' ('+weekWord(weeks)+')';return yearWord+' '+weekWord(rem)+' ('+weekWord(weeks)+')';}
function ypOwnedSinceWeek(rec){if(!rec)return NaN;const week=typeof ypWeekNow==='function'?ypWeekNow():((typeof G!=='undefined'&&G)?(G.week|0):0);if(typeof ypLoanSettleWeek==='function'){const w=ypLoanSettleWeek(rec,week);if(Number.isFinite(w))return w|0;}if(Number.isFinite(+rec.settleWeek))return +rec.settleWeek|0;if(Number.isFinite(+rec.settleGameMs)&&typeof ypWeekFromGameMs==='function'){const w=ypWeekFromGameMs(+rec.settleGameMs);if(Number.isFinite(w))return w|0;}return NaN;}
